/**
 * Pure vocabulary of the durable composition manifest: one entry per component
 * in play, the composition hash that addresses the whole set, and the
 * `SessionEventMap` declaration that records it. Free of cordis, agent, and
 * service imports so the writer, the fold, and the invariant companion share
 * one home.
 *
 * @module @deepseek-ai/dsh-components-manifest/types
 */

import type {
  ComponentDigest,
  ComponentDigestBasis,
  ComponentId,
  ComponentKind,
  ComponentLayer,
  ComponentProvenance,
} from '@deepseek-ai/dsh-components/types'

/** Self-declared payload version of the manifest this build writes. */
export const COMPOSITION_MANIFEST_VERSION = 1

/** One component in play, as the manifest records it. */
export interface CompositionManifestEntry {
  /** Stable component identity; with {@link digest} it forms the `id@digest` address. */
  readonly id: ComponentId
  /** Content address of the generation in play. */
  readonly digest: ComponentDigest
  /** The component's declared kind. */
  readonly kind: ComponentKind
  /** Whether the digest covers the component's own bytes or only its registration. */
  readonly digestBasis: ComponentDigestBasis
  /** Whether people curated the component or an agent synthesized it. */
  readonly provenance: ComponentProvenance
  /** Component this generation derived from, absent for roots. */
  readonly lineage?: ComponentId
  /** Registry layer the winning registration sat in for the recording agent. */
  readonly layer: ComponentLayer
}

/** The durable record of every component one agent had in play at one step. */
export interface CompositionManifest {
  /** Payload version, so a later field addition is readable against a stated shape. */
  readonly version: typeof COMPOSITION_MANIFEST_VERSION
  /** Every component in play, ordered by `id@digest` address. */
  readonly components: readonly CompositionManifestEntry[]
  /** Lowercase SHA-256 hex over the ordered addresses joined by newlines. */
  readonly compositionSha256: string
}

declare module '@deepseek-ai/dsh-session/types' {
  interface SessionEventMap {
    /**
     * Every component one agent had in play when a step was proposed: its
     * `id@digest` address, kind, digest basis, provenance, lineage, and the
     * registry layer the winning registration sat in, ordered by address, with
     * `compositionSha256` hashing that ordered address list. Log-only, and
     * written only when the hash differs from the last manifest in the same
     * log, so a stable composition records exactly one event and a resumed
     * session re-emits nothing. Required on read: a build that cannot
     * interpret it would otherwise treat a composition it cannot name as a
     * known one.
     */
    'composition/manifest': CompositionManifest
  }
}

/**
 * Pure derivations over the composition manifest: the address list one registry
 * reading produces, the hash that addresses the whole set, and the last
 * manifest a durable log recorded.
 *
 * @module @deepseek-ai/dsh-components-manifest/fold
 */

import { createHash } from 'node:crypto'
import { componentAddress } from '@deepseek-ai/dsh-components'
import type { ComponentView } from '@deepseek-ai/dsh-components/types'
import type { SessionEvent } from '@deepseek-ai/dsh-session'
import { COMPOSITION_MANIFEST_VERSION } from './types.ts'
import type { CompositionManifest, CompositionManifestEntry } from './types.ts'

/** An `id@digest` address whose digest is a full lowercase SHA-256 hex. */
const ADDRESS = /^[^\n@]+@[0-9a-f]{64}$/

/**
 * Whether one `id@digest` address is well-formed: a non-empty id carrying no
 * separator and no newline, then the full 64-character lowercase digest a
 * comparison keys on.
 * @param address - the candidate address.
 * @returns whether the address can be compared against another generation's.
 */
export function isComponentAddress(address: string): boolean {
  return ADDRESS.test(address)
}

/**
 * Hash one ordered address list.
 * @param addresses - the `id@digest` addresses in manifest order.
 * @returns the lowercase SHA-256 hex over the addresses joined by newlines.
 */
export function compositionSha256(addresses: readonly string[]): string {
  return createHash('sha256').update(addresses.join('\n')).digest('hex')
}

/**
 * Project one registry reading onto the manifest entries, ordered by address so
 * two hosts that composed the same set hash it identically.
 * @param views - the components one agent sees, as `ctx.components.list()` returns them.
 * @returns one entry per component, ascending by `id@digest`.
 */
export function manifestEntries(views: readonly ComponentView[]): CompositionManifestEntry[] {
  return views
    .map((view): CompositionManifestEntry => ({
      id: view.id,
      digest: view.digest,
      kind: view.kind,
      digestBasis: view.digestBasis,
      provenance: view.provenance,
      ...view.lineage === undefined ? {} : { lineage: view.lineage },
      layer: view.layer,
    }))
    // Code-unit comparison, so the order is identical on every machine.
    .sort((left, right) => {
      const a = componentAddress(left.id, left.digest)
      const b = componentAddress(right.id, right.digest)
      return a < b ? -1 : a > b ? 1 : 0
    })
}

/**
 * Build the durable manifest of one registry reading.
 * @param views - the components one agent sees, as `ctx.components.list()` returns them.
 * @returns the payload to append, hashed over its own ordered addresses.
 */
export function buildCompositionManifest(views: readonly ComponentView[]): CompositionManifest {
  const components = manifestEntries(views)
  return {
    version: COMPOSITION_MANIFEST_VERSION,
    components,
    compositionSha256: compositionSha256(components.map(entry => componentAddress(entry.id, entry.digest))),
  }
}

/**
 * The newest manifest a durable log recorded.
 * @param events - the session's event log, oldest first.
 * @returns the last recorded manifest, or `undefined` when the log holds none.
 */
export function lastCompositionManifest(events: readonly SessionEvent[]): CompositionManifest | undefined {
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const event = events[index]
    if (event?.type === 'composition/manifest') return event.data
  }
  return undefined
}

/**
 * Composition manifest writer. Before every proposed step it recomputes the
 * components the calling agent has in play, addresses the whole set with one
 * `compositionSha256`, and appends a `composition/manifest` event only when
 * that hash differs from the last one the session log recorded.
 *
 * Recomputing rather than tracking incrementally is what keeps the record
 * correct across a producer's HMR disposal, a preset mounted after creation,
 * and scope shadowing: the writer holds no subscription state any of those
 * orderings could invalidate.
 *
 * @module @deepseek-ai/dsh-components-manifest
 */

import type { Context } from '@deepseek-ai/cordis'
import type { PreStepDecision } from '@deepseek-ai/dsh-agent'
// Type-only: resolves ctx.components and the registry's read options.
import type {} from '@deepseek-ai/dsh-components'
import { buildCompositionManifest, lastCompositionManifest } from './fold.ts'

// The pure payload outlet (./types.ts, the ONE home of the
// `composition/manifest` declaration) re-exported onto the package root keeps
// the module edge in the emitted index.d.ts, so aggregate programs consuming
// the declaration still receive the SessionEventMap merge.
export type * from './types.ts'
export { COMPOSITION_MANIFEST_VERSION } from './types.ts'
export {
  buildCompositionManifest, compositionSha256, isComponentAddress, lastCompositionManifest, manifestEntries,
} from './fold.ts'

/** Cordis plugin name used by loader diagnostics. */
export const name = 'components-manifest'

/** The agent registry that owns pre-step processing, and the inventory the manifest records. */
export const inject = ['agents', 'components']

/**
 * Record the composition before every proposed step.
 *
 * `next()` runs first so the reading covers what the whole pre-step chain
 * settled on, and the manifest is written for the step that was proposed even
 * when a later policy rejected it: the composition was in play either way, and
 * the deduplication key keeps a stable one to exactly one event.
 * @param ctx - plugin context; the listener is disposed with it.
 */
export function apply(ctx: Context): void {
  ctx.on('agent/pre-step', async ({ agent }, next): Promise<PreStepDecision> => {
    const decision = await next()
    const manifest = buildCompositionManifest(ctx.components.list({ scope: agent }))
    if (lastCompositionManifest(agent.session.events)?.compositionSha256 !== manifest.compositionSha256) {
      agent.session.append('composition/manifest', manifest)
    }
    return decision
  })
}

/**
 * Package-owned invariant over the durable record this package writes.
 *
 * Two manifests in a row that state the same `compositionSha256` would mean the
 * writer appended a record no composition change produced, which is exactly the
 * deduplication a consumer folding the log relies on. Every entry must also
 * carry a comparable address: an id with no separator and no newline, and the
 * full 64-character lowercase digest, because a truncated or malformed one
 * silently fails every generation comparison keyed on it.
 *
 * @module @deepseek-ai/dsh-components-manifest/invariant
 */

import type { Context } from '@deepseek-ai/cordis'
import { componentAddress } from '@deepseek-ai/dsh-components'
import type { InvariantFailure, InvariantInstaller } from '@deepseek-ai/dsh-invariants'
import type { Session, SessionEvent } from '@deepseek-ai/dsh-session'
import { isComponentAddress, lastCompositionManifest } from './fold.ts'
import type { CompositionManifest } from './types.ts'

const PACKAGE_NAME = '@deepseek-ai/dsh-components-manifest'

/** Cordis companion plugin name. */
export const name = 'components-manifest-invariant'
/** Service required before the companion can reserve package ownership. */
export const inject = ['invariants']

/** Validate one recorded manifest against the durable prefix that precedes it. */
function validateManifest(
  prior: readonly SessionEvent[],
  manifest: CompositionManifest,
  fail: InvariantFailure,
): void {
  const previous = lastCompositionManifest(prior)
  if (previous?.compositionSha256 === manifest.compositionSha256) {
    fail(`composition/manifest repeats compositionSha256 ${manifest.compositionSha256}, which the preceding manifest already recorded`)
  }
  for (const entry of manifest.components) {
    const address = componentAddress(entry.id, entry.digest)
    if (isComponentAddress(address)) continue
    fail(`composition/manifest lists component address ${JSON.stringify(address)}, which no generation comparison can key on`)
  }
}

/** Validate one candidate event against the durable prefix that precedes it. */
function validateEvent(
  prior: readonly SessionEvent[],
  event: SessionEvent,
  fail: InvariantFailure,
): void {
  if (event.type === 'composition/manifest') validateManifest(prior, event.data, fail)
}

/** Check existing sessions and every candidate event before Session publishes it. */
const install: InvariantInstaller = Object.assign((ctx: Context, fail: InvariantFailure) => {
  for (const session of ctx.sessions.list()) {
    const prior: SessionEvent[] = []
    for (const event of session.events) {
      validateEvent(prior, event, fail)
      prior.push(event)
    }
  }
  /* jscpd:ignore-start -- package companions share dispatch and registration plumbing */
  ctx.on('internal/dispatch', (_mode, eventName, args) => {
    if (eventName !== 'session/event') return
    const [session, event] = args as [Session, SessionEvent]
    validateEvent(session.events, event, fail)
  }, { global: true })
}, { inject: ['sessions'] })

/**
 * Register the composition-manifest invariant companion.
 * @param ctx - Cordis context carrying the invariant service.
 * @returns the installed registration's disposer after setup succeeds.
 */
export const apply = (ctx: Context): Promise<() => void> =>
  Promise.resolve(ctx.invariants.register(PACKAGE_NAME, install))
/* jscpd:ignore-end */

