    .not.toBe(manifest.compositionSha256)
  // Two readings of one address keep their relative order rather than swapping.
  expect(manifestEntries([view('a', 'one'), view('a', 'one')]).map(entry => entry.id)).toEqual(['a', 'a'])
})

